shader_body
{
    float2 p = (uv - 0.5) * aspect.xy;
    float r = length(p);
    float2 safeP = p / max(r, 0.00001);

    float pulse = q1 * 0.08;
    float3 L = normalize(float3(0.0, -1.0, 1.5 - q7));
    float3 bg = float3(0.015, 0.015, 0.015);
    ret = bg;
    float scale = 0.90;

    float frameOuter = 1.0 - smoothstep(0.47 * scale, 0.48 * scale, r);
    float frameInner = smoothstep(0.39 * scale, 0.40 * scale, r);
    float frameMask = frameOuter * frameInner;
    float3 frameN = normalize(float3(p, 0.20));
    float frameShade = 0.5 + 0.5 * dot(frameN, L);
    float frameY = saturate((p.y / (0.48 * scale)) * 0.5 + 0.5);
    float3 frameGrad = lerp(float3(0.18, 0.18, 0.19), float3(0.04, 0.04, 0.045), frameY);
    float3 frameCol = frameGrad + frameShade * 0.025;

    float angle = atan2(p.y, p.x);
    float sector = 6.28318530 / 8.0;
    float holeIndex = floor((angle + sector * 0.5) / sector);
    float holeAngle = holeIndex * sector;
    float holeRadius = 0.435 * scale;
    float2 holeCenter = float2(cos(holeAngle), sin(holeAngle)) * holeRadius;
    float holeDist = length(p - holeCenter);
    float holeSize = 0.012 * scale;
    float holeBezel = 0.018 * scale;
    float holeMask = 1.0 - smoothstep(holeSize - 0.002 * scale, holeSize, holeDist);
    float bezelMask = (1.0 - smoothstep(holeBezel - 0.002 * scale, holeBezel, holeDist)) * (1.0 - holeMask);
    float3 darkRimCol = float3(0.010, 0.010, 0.012);
    float3 darkCenterCol = float3(0.015, 0.015, 0.018) + frameShade * 0.01;
    frameCol = lerp(frameCol, darkRimCol, bezelMask);
    frameCol = lerp(frameCol, darkCenterCol, holeMask);
    ret = lerp(ret, frameCol, frameMask);

    float surrCenter = (0.36 + pulse * 0.03) * scale;
    float surrWidth = 0.045 * scale;
    float surrDist = abs(r - surrCenter);
    float surrMask = 1.0 - smoothstep(surrWidth - 0.005 * scale, surrWidth, surrDist);
    float surrNX = (r - surrCenter) / max(surrWidth, 0.00001);
    float surrNZ = sqrt(max(0.0, 1.0 - surrNX * surrNX));
    float3 surrN = normalize(float3(safeP * surrNX, surrNZ));
    float surrDiff = pow(max(0.0, dot(surrN, L)), 1.05);
    float3 surrCol = float3(0.035, 0.037, 0.040) + surrDiff * 0.10 + pow(surrDiff, 7.0) * 0.53;
    ret = lerp(ret, surrCol, surrMask);

    float excursion = q1 * 0.06;
    float r_cone = r * (1.0 - excursion);
    float coneInner = (0.12 - pulse * 0.02) * scale;
    float coneOuter = (0.32 + pulse * 0.06) * scale;
    float coneMask = (1.0 - smoothstep(coneOuter - 0.005 * scale, coneOuter, r)) * smoothstep(coneInner, coneInner + 0.01 * scale, r);
    float grooves = 0.5 + 0.5 * sin((r_cone * 400.0 / scale) - excursion * 15.0);
    float grooveLight = pow(max(0.0, dot(safeP, L.xy)), 1.15) * grooves;
    float coneDepth = saturate((r_cone - coneInner) / max(coneOuter - coneInner, 0.00001));
    float yPos = saturate((p.y - (-coneOuter)) / max(2.0 * coneOuter, 0.00001));
    float3 cConeBlack = float3(0.035, 0.035, 0.04);
    float3 cConeAmber = float3(0.95, 0.45, 0.05);
    float3 coneBase = lerp(cConeAmber, cConeBlack, yPos);
    float bVal = saturate(q1);
    float hVal = time * 0.2 + r_cone * (12.0 + bVal * 10.0) + sin(r_cone * 30.0 - time * 6.0 + excursion * 12.0) * bVal * 4.0;
    float wavePattern = pow(0.5 + 0.5 * sin(hVal), 1.0 + bVal * 3.0);
    float3 cAmberWave = float3(1.0, 0.80, 0.35) * wavePattern * (0.4 + bVal * 0.8) * 0.20;
    coneBase += cAmberWave;
    coneBase *= 0.35 + coneDepth * 0.65;
    coneBase += grooveLight * 0.53 * 0.40;
    coneBase *= 0.75 + 0.25 * max(0.0, dot(safeP, L.xy));
    ret = lerp(ret, max(coneBase, bg), coneMask);

    float capSize = (0.13 + pulse * 0.02) * scale;
    float capMask = 1.0 - smoothstep(capSize - 0.005 * scale, capSize, r);
    float2 capP = p / max(capSize, 0.00001);
    float capZ = sqrt(max(0.0, 1.0 - dot(capP, capP)));
    float3 capN = normalize(float3(capP, capZ));
    float capDiff = pow(max(0.0, dot(capN, L)), 1.05);
    float3 Rvec = reflect(-L, capN);
    float capSpec = pow(max(0.0, dot(Rvec, float3(0.0, 0.0, 1.0))), 24.0);
    float capY = saturate(capP.y * 0.5 + 0.5);
    float3 capGrad = lerp(float3(0.18, 0.18, 0.19), float3(0.04, 0.04, 0.045), capY);
    float3 capCol = capGrad + capDiff * 0.05 + capSpec * 0.53 * 0.40;

    float2 wp_base = capP * 1.5;
    float2 dP = float2(wp_base.x * 0.7071 - wp_base.y * 0.7071, wp_base.x * 0.7071 + wp_base.y * 0.7071);
    float dMax = max(abs(dP.x), abs(dP.y));
    float diamondA_fill = 1.0 - smoothstep(0.50, 0.53, dMax);
    float diamondA_interior = 1.0 - smoothstep(0.42, 0.45, dMax);
    float diamondA_border = diamondA_fill - diamondA_interior;

    float2 wp_base2 = capP * 1.5;
    float2 dP2 = float2(wp_base2.x * 0.7071 - wp_base2.y * 0.7071, wp_base2.x * 0.7071 + wp_base2.y * 0.7071);
    float dMax2 = max(abs(dP2.x), abs(dP2.y));
    float diamondB_fill = 1.0 - smoothstep(0.50, 0.53, dMax2);
    float diamondB_interior = 1.0 - smoothstep(0.42, 0.45, dMax2);
