    bp.x = -bp.x;
    float2 v0 = float2( 0.42,  0.48);
    float2 v1 = float2( 0.18,  0.16);
    float2 v2 = float2( 0.28,  0.12);
    float2 v3 = float2( 0.28, -0.06);
    float2 v4 = float2(-0.42, -0.48);
    float2 v5 = float2(-0.18, -0.16);
    float2 v6 = float2(-0.28, -0.12);
    float2 v7 = float2(-0.28,  0.06);
    float hits = 0.0;
    hits += step(0.0, (v0.y - bp.y) * (bp.y - v1.y)) * step(bp.x, (v1.x - v0.x) * (bp.y - v0.y) / (v1.y - v0.y + 0.00001) + v0.x);
    hits += step(0.0, (v1.y - bp.y) * (bp.y - v2.y)) * step(bp.x, (v2.x - v1.x) * (bp.y - v1.y) / (v2.y - v1.y + 0.00001) + v1.x);
    hits += step(0.0, (v2.y - bp.y) * (bp.y - v3.y)) * step(bp.x, (v3.x - v2.x) * (bp.y - v2.y) / (v3.y - v2.y + 0.00001) + v2.x);
    hits += step(0.0, (v3.y - bp.y) * (bp.y - v4.y)) * step(bp.x, (v4.x - v3.x) * (bp.y - v3.y) / (v4.y - v3.y + 0.00001) + v3.x);
    hits += step(0.0, (v4.y - bp.y) * (bp.y - v5.y)) * step(bp.x, (v5.x - v4.x) * (bp.y - v4.y) / (v5.y - v4.y + 0.00001) + v4.x);
    hits += step(0.0, (v5.y - bp.y) * (bp.y - v6.y)) * step(bp.x, (v6.x - v5.x) * (bp.y - v5.y) / (v6.y - v5.y + 0.00001) + v5.x);
    hits += step(0.0, (v6.y - bp.y) * (bp.y - v7.y)) * step(bp.x, (v7.x - v6.x) * (bp.y - v6.y) / (v7.y - v6.y + 0.00001) + v6.x);
    hits += step(0.0, (v7.y - bp.y) * (bp.y - v0.y)) * step(bp.x, (v0.x - v7.x) * (bp.y - v7.y) / (v0.y - v7.y + 0.00001) + v7.x);
    float inBolt = fmod(hits, 2.0);
    float d0 = length(bp - (v0 + clamp(dot(bp - v0, v1 - v0) / dot(v1 - v0, v1 - v0), 0.0, 1.0) * (v1 - v0)));
    float d1 = length(bp - (v1 + clamp(dot(bp - v1, v2 - v1) / dot(v2 - v1, v2 - v1), 0.0, 1.0) * (v2 - v1)));
    float d2 = length(bp - (v2 + clamp(dot(bp - v2, v3 - v2) / dot(v3 - v2, v3 - v2), 0.0, 1.0) * (v3 - v2)));
    float d3 = length(bp - (v3 + clamp(dot(bp - v3, v4 - v3) / dot(v4 - v3, v4 - v3), 0.0, 1.0) * (v4 - v3)));
    float d4 = length(bp - (v4 + clamp(dot(bp - v4, v5 - v4) / dot(v5 - v4, v5 - v4), 0.0, 1.0) * (v5 - v4)));
    float d5 = length(bp - (v5 + clamp(dot(bp - v5, v6 - v5) / dot(v6 - v5, v6 - v5), 0.0, 1.0) * (v6 - v5)));
    float d6 = length(bp - (v6 + clamp(dot(bp - v6, v7 - v6) / dot(v7 - v6, v7 - v6), 0.0, 1.0) * (v7 - v6)));
    float d7 = length(bp - (v7 + clamp(dot(bp - v7, v0 - v7) / dot(v0 - v7, v0 - v7), 0.0, 1.0) * (v0 - v7)));
