    float boltEdgeSmooth = smoothstep(0.0, 0.015, minEdgeDist);
    float boltCore = lerp(1.0 - boltEdgeSmooth, boltEdgeSmooth, inBolt);
    float boltOutline = smoothstep(0.065, 0.080, minEdgeDist);
