    float3 goldLight = float3(1.00, 0.85, 0.25);
    float3 goldDark  = float3(0.85, 0.48, 0.05);
    float3 goldCol   = lerp(goldDark, goldLight, goldGradient);
    float3 whiteCol  = float3(0.95, 0.95, 0.95);
    float3 grayCol   = float3(0.80, 0.80, 0.80);
    float3 blackOutlineCol = float3(0.02, 0.02, 0.02);

