    float logoGlint = capSpec * 0.85;
    blackOutlineCol = saturate(blackOutlineCol * logoShade + logoGlint * 0.35);
    whiteCol = saturate(whiteCol * logoShade + logoGlint);
    grayCol = saturate(grayCol * logoShade + logoGlint * 0.80);
    goldCol = saturate(goldCol * logoShade + logoGlint);

    capCol = lerp(capCol, blackOutlineCol, diamondB_border * capMask);
