    capCol = lerp(capCol, whiteCol, diamondA_interior * capMask);
    capCol = lerp(capCol, blackOutlineCol, boltOutlineMask * capMask);
    capCol = lerp(capCol, goldCol, boltCore * capMask);
    ret = lerp(ret, capCol, capMask);

    float ao = (0.55 + 0.45 * smoothstep(0.0, 0.06 * scale, abs(r - coneOuter))) * (0.65 + 0.35 * smoothstep(0.0, 0.04 * scale, abs(r - capSize)));
